insert into public.articles (slug, title, summary, cover_image_url, content_html, category, status, locale, published_at) values
('guide-to-hiring-housemaid','الدليل الكامل لاستقدام خادمة منزلية في قطر','كل ما تحتاج معرفته عن إجراءات الاستقدام والشروط القانونية.','https://placehold.co/600x400?text=Guide','<p>استقدام خادمة منزلية في قطر يتطلب اتباع إجراءات قانونية محددة تبدأ بالحصول على الترخيص المناسب... (محتوى تجريبي كامل)</p><p>هذا مقال تجريبي (Demo) ضمن منصة خدَم قطر للاستقدام المنزلي. المحتوى قابل للاستبدال لاحقاً بمحتوى حقيقي.</p>','دلائل','published','ar',now()),
('filipino-maids-qatar','مساعدات فلبينيات في قطر: المزايا والتوقعات','نظرة على خصائص المساعدات الفلبينيات وما يميزهن في سوق العمل المنزلي.','https://placehold.co/600x400?text=Filipino','<p>تعتبر المساعدات الفلبينيات من أكثر الخيارات طلباً في قطر لخبرتهن وإتقانهن اللغة الإنجليزية...</p><p>هذا مقال تجريبي (Demo) ضمن منصة خدَم قطر للاستقدام المنزلي. المحتوى قابل للاستبدال لاحقاً بمحتوى حقيقي.</p>','جنسيات','published','ar',now()),
('ethiopian-maids-qatar','المساعدات الإثيوبيات في قطر: ما يميزهن','تعرف على خصائص المساعدات الإثيوبيات وكيفية التوافق معهن.','https://placehold.co/600x400?text=Ethiopian','<p>تتميز المساعدات الإثيوبيات بقربهن الثقافي من المجتمع العربي وإتقانهن اللغة العربية...</p><p>هذا مقال تجريبي (Demo) ضمن منصة خدَم قطر للاستقدام المنزلي. المحتوى قابل للاستبدال لاحقاً بمحتوى حقيقي.</p>','نصائح','published','ar',now()),
('ugandan-maids-qatar','المساعدات الأوغنديات في قطر: لمحة عامة','نظرة عامة على المساعدات الأوغنديات في سوق العمل المنزلي القطري.','https://placehold.co/600x400?text=Ugandan','<p>تقدم المساعدات الأوغنديات خياراً اقتصادياً مرناً مع خبرة جيدة في رعاية المنزل...</p><p>هذا مقال تجريبي (Demo) ضمن منصة خدَم قطر للاستقدام المنزلي. المحتوى قابل للاستبدال لاحقاً بمحتوى حقيقي.</p>','قانون','published','ar',now()),
('live-in-vs-live-out','الإقامة الكاملة مقابل العمل بالساعة: أيهما تختار؟','مقارنة بين أنواع عقود العمل المنزلي ومميزات كل نوع.','https://placehold.co/600x400?text=Compare','<p>يعتمد الاختيار بين الإقامة الكاملة والعمل بالساعة على احتياجات الأسرة وميزانيتها...</p><p>هذا مقال تجريبي (Demo) ضمن منصة خدَم قطر للاستقدام المنزلي. المحتوى قابل للاستبدال لاحقاً بمحتوى حقيقي.</p>','تكاليف','published','ar',now()),
('interview-tips','نصائح لإجراء مقابلة ناجحة مع المرشحة','كيف تستعد للمقابلة وتختار المرشحة المناسبة لمنزلك.','https://placehold.co/600x400?text=Interview','<p>المقابلة الجيدة هي مفتاح الاختيار الناجح...</p><p>هذا مقال تجريبي (Demo) ضمن منصة خدَم قطر للاستقدام المنزلي. المحتوى قابل للاستبدال لاحقاً بمحتوى حقيقي.</p>','مهارات','published','ar',now()),
('training-importance','أهمية تدريب الخادمات قبل الاستقدام','لماذا يعتبر التدريب المسبق عاملاً مهماً في جودة الخدمة.','https://placehold.co/600x400?text=Training','<p>التدريب المسبق يقلل من مشاكل التأقلم ويزيد من كفاءة العمل...</p><p>هذا مقال تجريبي (Demo) ضمن منصة خدَم قطر للاستقدام المنزلي. المحتوى قابل للاستبدال لاحقاً بمحتوى حقيقي.</p>','سلامة','published','ar',now()),
('legal-rights','حقوق وواجبات صاحب العمل والخادمة','ملخص الحقوق والواجبات القانونية للأطراف.','https://placehold.co/600x400?text=Rights','<p>تحفظ قوانين قطر حقوق جميع الأطراف وتحدد الواجبات بوضوح...</p><p>هذا مقال تجريبي (Demo) ضمن منصة خدَم قطر للاستقدام المنزلي. المحتوى قابل للاستبدال لاحقاً بمحتوى حقيقي.</p>','سياسات','published','ar',now()),
('cost-breakdown','تفصيل تكاليف الاستقدام في قطر','شرح بنود التكاليف المتوقعة عند الاستقدام.','https://placehold.co/600x400?text=Cost','<p>تشمل التكاليف رسوم التأشيرة والرحلة والعقد وغيرها...</p><p>هذا مقال تجريبي (Demo) ضمن منصة خدَم قطر للاستقدام المنزلي. المحتوى قابل للاستبدال لاحقاً بمحتوى حقيقي.</p>','ثقافة','published','ar',now()),
('nanny-vs-housemaid','الفرق بين المربية والخادمة المنزلية','متى تحتاج مربية ومتى تحتاج خادمة عامة.','https://placehold.co/600x400?text=Nanny','<p>تختلف المهارات المطلوبة حسب طبيعة العمل المنزلي...</p><p>هذا مقال تجريبي (Demo) ضمن منصة خدَم قطر للاستقدام المنزلي. المحتوى قابل للاستبدال لاحقاً بمحتوى حقيقي.</p>','حياة يومية','published','ar',now()),
('elderly-care','رعاية المسنين في المنزل: دليل عملي','كيف تختار مرشحة مناسبة لرعاية المسنين.','https://placehold.co/600x400?text=Elderly','<p>رعاية المسنين تتطلب مهارات خاصة وصبراً...</p><p>هذا مقال تجريبي (Demo) ضمن منصة خدَم قطر للاستقدام المنزلي. المحتوى قابل للاستبدال لاحقاً بمحتوى حقيقي.</p>','دلائل','published','ar',now()),
('cooking-skills','مهارات الطبخ المتوقرة من الخادمة','ما المستوى المتوقع من مهارات الطبخ.','https://placehold.co/600x400?text=Cooking','<p>يختلف توقع مهارات الطبخ حسب الخلفية الثقافية...</p><p>هذا مقال تجريبي (Demo) ضمن منصة خدَم قطر للاستقدام المنزلي. المحتوى قابل للاستبدال لاحقاً بمحتوى حقيقي.</p>','جنسيات','published','ar',now()),
